prompt:
Create one plausible and distinct RTL bug in this reference design.
Do not change any interface, add system tasks, include files, or generate a testbench.
Choose a substantially different implementation mistake from these existing proposals:
Zeroes port A output whenever its registered enable is low instead of updating it from memory.
Uses port A's byte-enable bit for port A's second byte during same-address collisions.
Gives port B priority over port A for the lowest byte during same-address collisions.
Captures port A's address into the port B address register, causing port B accesses to target the wrong location.
Reads port A using the current input address rather than the registered address, changing its read timing.
Port B writes byte lane 2 using the adjacent byte of input data.
Same-address handling activates even when neither port is enabled.
Port B's highest byte lane is controlled by the wrong byte enable.
Port B's read output does not update while its registered enable is low.
Return JSON only as {"mutants":[{"bug":"short description","edits":[{"old":"verbatim unique text","new":"replacement"}]}]}.
The 'old' text must occur exactly once in this original RTL. Choose a change to an executable expression.
Reference RTL:
module custom_byte_enable_ram 
  #(
    parameter XLEN  = 32,
    parameter LINES = 8192
  )
  (
    input  logic                     clk,
    input  logic[$clog2(LINES)-1:0]  addr_a,
    input  logic                     en_a,
    input  logic[XLEN/8-1:0]         be_a,
    input  logic[XLEN-1:0]           data_in_a,
    output logic[XLEN-1:0]           data_out_a,
    input  logic[$clog2(LINES)-1:0]  addr_b,
    input  logic                     en_b,
    input  logic[XLEN/8-1:0]         be_b,
    input  logic[XLEN-1:0]           data_in_b,
    output logic[XLEN-1:0]           data_out_b
  );

  localparam ADDR_WIDTH = $clog2(LINES);

  logic [XLEN-1:0] ram [LINES-1:0];

  logic [ADDR_WIDTH-1:0] addr_a_reg;
  logic                  en_a_reg;
  logic [XLEN/8-1:0]     be_a_reg;
  logic [XLEN-1:0]       data_in_a_reg;

  logic [ADDR_WIDTH-1:0] addr_b_reg;
  logic                  en_b_reg;
  logic [XLEN/8-1:0]     be_b_reg;
  logic [XLEN-1:0]       data_in_b_reg;

  initial begin
    for(int i = 0 ; i < LINES ; i++) begin
       ram[i] <= '0;
    end
  end

  always_ff @(posedge clk) begin
    addr_a_reg    <= addr_a;
    en_a_reg      <= en_a;
    be_a_reg      <= be_a;
    data_in_a_reg <= data_in_a;

    addr_b_reg    <= addr_b;
    en_b_reg      <= en_b;
    be_b_reg      <= be_b;
    data_in_b_reg <= data_in_b;
  end

  always_ff @(posedge clk) begin
    if (en_a_reg && en_b_reg && (addr_a_reg == addr_b_reg)) begin
      if (be_a_reg[0])
        ram[addr_a_reg][7:0] <= data_in_a_reg[7:0];
      else if (be_b_reg[0])
        ram[addr_a_reg][7:0] <= data_in_b_reg[7:0];


      if (be_a_reg[1])
        ram[addr_a_reg][15:8] <= data_in_a_reg[15:8];
      else if (be_b_reg[1])
        ram[addr_a_reg][15:8] <= data_in_b_reg[15:8];

      if (be_a_reg[2])
        ram[addr_a_reg][23:16] <= data_in_a_reg[23:16];
      else if (be_b_reg[2])
        ram[addr_a_reg][23:16] <= data_in_b_reg[23:16];

      if (be_a_reg[3])
        ram[addr_a_reg][31:24] <= data_in_a_reg[31:24];
      else if (be_b_reg[3])
        ram[addr_a_reg][31:24] <= data_in_b_reg[31:24];
    end 
    else begin
      if (en_a_reg) begin
        if (be_a_reg[0])
          ram[addr_a_reg][7:0] <= data_in_a_reg[7:0];
        if (be_a_reg[1])
          ram[addr_a_reg][15:8] <= data_in_a_reg[15:8];
        if (be_a_reg[2])
          ram[addr_a_reg][23:16] <= data_in_a_reg[23:16];
        if (be_a_reg[3])
          ram[addr_a_reg][31:24] <= data_in_a_reg[31:24];
      end

      if (en_b_reg) begin
        if (be_b_reg[0])
          ram[addr_b_reg][7:0] <= data_in_b_reg[7:0];
        if (be_b_reg[1])
          ram[addr_b_reg][15:8] <= data_in_b_reg[15:8];
        if (be_b_reg[2])
          ram[addr_b_reg][23:16] <= data_in_b_reg[23:16];
        if (be_b_reg[3])
          ram[addr_b_reg][31:24] <= data_in_b_reg[31:24];
      end
    end

    data_out_a <= ram[addr_a_reg];
    data_out_b <= ram[addr_b_reg];
  end

endmodule
